    private fun norm(t: String) = t.lowercase().replace('ё', 'е')

    /** Entries whose section/screen name or any label contains every word of [query]. Names first. */
    fun search(query: String): List<Entry> {
        val words = norm(query).split(' ').filter { it.isNotBlank() }
        if (words.isEmpty()) return emptyList()
        fun hay(e: Entry) = norm((listOfNotNull(e.section) + e.keys).joinToString(" "))
        return all.filter { e -> val h = hay(e); words.all { it in h } }
            .sortedBy { e -> if (words.all { norm(e.section ?: e.keys.first()).contains(it) }) 0 else 1 }
    }
}
